	sub := args[0]
	rest := args[1:]
	switch sub {
	case "create":
		circuitCreate(rest)
	case "update":
		circuitUpdate(rest)
	case "freeze":
		circuitFreeze(rest)
	case "list":
		circuitList(rest)
	default:
