// load reads all three data files. A missing file means an empty
// collection; a truncated, malformed, or unsupported file is reported as
// ErrCorruptData and the file is never modified.
func (s *Store) load() (*storeData, error) {
	data := &storeData{}
	targets := []struct {
		name string
		dst  any
	}{
		{circuitsFile, &data.Circuits},
		{setupsFile, &data.Setups},
		{jobsFile, &data.Jobs},
	}
	for _, t := range targets {
		raw, err := os.ReadFile(filepath.Join(s.dir, t.name))
		if os.IsNotExist(err) {
			continue
		}
		if err != nil {
			return nil, err
		}
		if len(raw) == 0 {
			return nil, fmt.Errorf("%w: %s is empty", ErrCorruptData, t.name)
		}
		var head struct {
			FormatVersion int `json:"format_version"`
		}
		if err := json.Unmarshal(raw, &head); err != nil {
			return nil, fmt.Errorf("%w: %s is not valid JSON: %v", ErrCorruptData, t.name, err)
		}
		if head.FormatVersion != FormatVersion {
			return nil, fmt.Errorf("%w: %s has format version %d, want %d", ErrCorruptData, t.name, head.FormatVersion, FormatVersion)
		}
		if err := json.Unmarshal(raw, t.dst); err != nil {
			return nil, fmt.Errorf("%w: %s is not valid data: %v", ErrCorruptData, t.name, err)
		}
	}
	return data, nil
}

